const require_index = require("../useEventListener/index.js");
let react = require("react");
//#region src/useDoubleClick/index.ts
const useDoubleClick = ({ target, latency = 300, onSingleClick = () => {}, onDoubleClick = () => {} }) => {
	const handle = (0, react.useCallback)((onSingleClick, onDoubleClick) => {
		let count = 0;
		return (e) => {
			if (e.type === "touchend") {
				e.stopPropagation();
				e.preventDefault();
			}
			count += 1;
			setTimeout(() => {
				if (count === 1) onSingleClick(e);
				else if (count === 2) onDoubleClick(e);
				count = 0;
			}, latency);
		};
	}, [latency]);
	const handleClick = handle(onSingleClick, onDoubleClick);
	const handleTouchEnd = handle(onSingleClick, onDoubleClick);
	require_index.useEventListener("click", handleClick, target);
	require_index.useEventListener("touchend", handleTouchEnd, target, { passive: false });
};
//#endregion
exports.useDoubleClick = useDoubleClick;
